SELECT 
  FROM pay06_act_mapping
 WHERE pay06_company_id = #{companyId}
   AND pay06_link_cd = #{linkCode}
   AND pay06_kind_cd LIKE #{kindCode}
 ORDER BY pay06_title COLLATE "ko_KR.utf8"

SELECT 
  FROM pay06_act_mapping
 WHERE pay06_act_mapping_id = #{actMappingId}
   AND pay06_company_id = #{companyId}

mapper.update:
UPDATE pay06_act_mapping
   SET pay06_title      = #{req.title},
       pay06_content    = #{req.content},
       pay06_link_cd    = #{req.linkCode},
       pay06_default_yn = COALESCE(CAST(#{req.defaultYn} AS VARCHAR), 'false'),
       pay06_note       = #{req.note},
       pay06_kind_cd    = #{req.kindCode}
 WHERE pay06_act_mapping_id = #{req.actMappingId}
   AND pay06_company_id = #{companyId}

mapper.delete:
DELETE FROM pay06_act_mapping
 WHERE pay06_company_id = #{companyId}
   AND pay06_act_mapping_id IN
#{id}
